:root {
  --bg: #1a1a2e;
  --card-bg: #16213e;
  --text: #e0e0e0;
  --accent: #0f3460;
  --highlight: #e94560;
  --btn-bg: #533483;
  --btn-hover: #6a4c9c;
  --btn-active: #3f2a6b;
  --focus: #e94560;
  --font: 'Courier New', Courier, monospace;
}

* {
  box-sizing: border-box;
  margin: 0;
  padding: 0;
}

body {
  background: var(--bg);
  color: var(--text);
  font-family: var(--font);
  font-size: 16px;
  min-height: 100vh;
  display: flex;
  align-items: center;
  justify-content: center;
  padding: 16px;
  image-rendering: pixelated;
}

.card {
  background: var(--card-bg);
  border: 4px solid var(--accent);
  padding: 32px 24px;
  text-align: center;
  max-width: 400px;
  width: 100%;
  box-shadow: 0 0 0 4px var(--bg), 0 0 0 8px var(--accent);
  image-rendering: pixelated;
}

.title {
  font-size: 1.5rem;
  letter-spacing: 2px;
  margin-bottom: 16px;
  color: var(--highlight);
  text-transform: uppercase;
}

.mode-indicator {
  font-size: 1rem;
  letter-spacing: 2px;
  margin-bottom: 8px;
  color: var(--text);
  opacity: 0.8;
  text-transform: uppercase;
}

.timer-display {
  font-size: 4rem;
  font-weight: bold;
  letter-spacing: 4px;
  margin: 16px 0 24px;
  color: var(--text);
  font-variant-numeric: tabular-nums;
  text-shadow: 3px 3px 0 var(--accent);
}

.controls {
  display: flex;
  gap: 12px;
  justify-content: center;
  margin-bottom: 16px;
  flex-wrap: wrap;
}

.btn {
  font-family: var(--font);
  font-size: 1rem;
  padding: 12px 24px;
  background: var(--btn-bg);
  color: var(--text);
  border: 3px solid var(--accent);
  cursor: pointer;
  letter-spacing: 1px;
  text-transform: uppercase;
  transition: background 0.1s, transform 0.1s;
  image-rendering: pixelated;
  min-width: 90px;
}

.btn:hover {
  background: var(--btn-hover);
}

.btn:focus-visible {
  outline: 3px solid var(--focus);
  outline-offset: 3px;
}

.btn:active {
  background: var(--btn-active);
  transform: translate(2px, 2px);
}

.mode-switch {
  display: flex;
  gap: 12px;
  justify-content: center;
  margin-bottom: 16px;
  flex-wrap: wrap;
}

.mode-btn {
  font-size: 0.875rem;
  padding: 8px 16px;
  min-width: 80px;
  opacity: 0.7;
}

.mode-btn.active {
  opacity: 1;
  border-color: var(--highlight);
  background: var(--btn-hover);
}

.status {
  font-size: 0.875rem;
  color: var(--highlight);
  min-height: 1.2em;
  letter-spacing: 1px;
  text-transform: uppercase;
}

@media (max-width: 400px) {
  .card {
    padding: 24px 16px;
  }
  .timer-display {
    font-size: 3rem;
  }
  .btn {
    padding: 10px 16px;
    min-width: 70px;
    font-size: 0.875rem;
  }
  .mode-btn {
    padding: 8px 12px;
    min-width: 60px;
    font-size: 0.75rem;
  }
}

@media (prefers-reduced-motion: reduce) {
  .btn {
    transition: none;
  }
}

const WORK_DURATION = 25 * 60;
const BREAK_DURATION = 5 * 60;

const timerDisplay = document.getElementById('timer-display');
const modeIndicator = document.getElementById('mode-indicator');
const startPauseBtn = document.getElementById('start-pause');
const resetBtn = document.getElementById('reset');
const modeWorkBtn = document.getElementById('mode-work');
const modeBreakBtn = document.getElementById('mode-break');
const statusEl = document.getElementById('status');

let mode = 'work';
let remaining = WORK_DURATION;
let isRunning = false;
let intervalId = null;
let endTime = 0;

function formatTime(seconds) {
  const m = Math.floor(seconds / 60);
  const s = seconds % 60;
  return `${String(m).padStart(2, '0')}:${String(s).padStart(2, '0')}`;
}

function updateDisplay() {
  timerDisplay.textContent = formatTime(remaining);
}

function updateModeUI() {
  const isWork = mode === 'work';
  modeIndicator.textContent = isWork ? 'Work' : 'Break';
  modeWorkBtn.classList.toggle('active', isWork);
  modeBreakBtn.classList.toggle('active', !isWork);
  modeWorkBtn.setAttribute('aria-pressed', isWork.toString());
  modeBreakBtn.setAttribute('aria-pressed', (!isWork).toString());
}

function setMode(newMode) {
  if (isRunning) return;
  mode = newMode;
  remaining = mode === 'work' ? WORK_DURATION : BREAK_DURATION;
  updateDisplay();
  updateModeUI();
  statusEl.textContent = '';
}

function tick() {
  const now = Date.now();
  const diff = Math.max(0, Math.round((endTime - now) / 1000));
  if (diff !== remaining) {
    remaining = diff;
    updateDisplay();
  }
  if (remaining <= 0) {
    stopTimer();
    statusEl.textContent = mode === 'work' ? 'Work session complete! Time for a break.' : 'Break over! Ready to work?';
    mode = mode === 'work' ? 'break' : 'work';
    remaining = mode === 'work' ? WORK_DURATION : BREAK_DURATION;
    updateDisplay();
    updateModeUI();
  }
}

function startTimer() {
  if (isRunning) return;
  isRunning = true;
  endTime = Date.now() + remaining * 1000;
  intervalId = setInterval(tick, 250);
  startPauseBtn.textContent = 'Pause';
  startPauseBtn.setAttribute('aria-label', 'Pause timer');
  statusEl.textContent = '';
}

function stopTimer() {
  if (intervalId !== null) {
    clearInterval(intervalId);
    intervalId = null;
  }
  isRunning = false;
  startPauseBtn.textContent = 'Start';
  startPauseBtn.setAttribute('aria-label', 'Start timer');
}

function toggleTimer() {
  if (isRunning) {
    stopTimer();
    remaining = Math.max(0, Math.round((endTime - Date.now()) / 1000));
    updateDisplay();
  } else {
    startTimer();
  }
}

function resetTimer() {
  stopTimer();
  remaining = mode === 'work' ? WORK_DURATION : BREAK_DURATION;
  updateDisplay();
  statusEl.textContent = '';
}

startPauseBtn.addEventListener('click', toggleTimer);
resetBtn.addEventListener('click', resetTimer);
modeWorkBtn.addEventListener('click', () => setMode('work'));
modeBreakBtn.addEventListener('click', () => setMode('break'));

updateDisplay();
updateModeUI();
